```choreo
__co__ void prod_consume(f32[N] in, f32[N] out) {
  shared event e;
  inthreads {
    buf = dma.copy.async in => local;
    trigger e;
  }
  inthreads {
    wait e;
    foreach i in 0..N {
      out[i] = buf[i] * 2;
    }
  }
}
